using System;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
namespace AkilliKisayol {
 public partial class MainWindow {
  readonly Dictionary<string,Button> navigation=new Dictionary<string,Button>();
  UIElement Navigation(){
   var panel=new StackPanel();
   var overview=NavGroup(panel,"OVERVIEW");AddNav(overview,"Home");AddNav(overview,"All shortcuts");
   var inputs=NavGroup(panel,"INPUTS");AddNav(inputs,"Keyboard shortcuts");AddNav(inputs,"Mouse shortcuts");AddNav(inputs,"Touchpad gestures");
   var workspace=NavGroup(panel,"WORKSPACE");AddNav(workspace,"Applications");AddNav(workspace,"AI model");
   var tools=new StackPanel();foreach(string name in new[]{"Profiles","Preferences","Shortcut guide","Computer shortcuts","Conflicts","History","Transfer and diagnostics","Appearance","Settings"})AddNav(tools,name);
   var label=Theme.Text("TOOLS & SETTINGS",11);label.FontWeight=FontWeights.Bold;var more=new Expander{Header=label,Content=tools,Margin=new Thickness(3,2,3,3),IsExpanded=false};System.Windows.Automation.AutomationProperties.SetName(more,"Tools and settings");var frame=new Border{Child=more,Padding=new Thickness(9),CornerRadius=new CornerRadius(9),BorderThickness=new Thickness(1),Margin=new Thickness(0,0,0,10)};frame.SetResourceReference(Border.BackgroundProperty,"Bg");frame.SetResourceReference(Border.BorderBrushProperty,"Line");panel.Children.Add(frame);
   return new ScrollViewer{Content=panel,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled};
  }
  StackPanel NavGroup(StackPanel panel,string title){var children=new StackPanel();var header=new StackPanel{Orientation=Orientation.Horizontal,Margin=new Thickness(7,4,4,8)};var marker=new Border{Width=3,Height=13,CornerRadius=new CornerRadius(2),Margin=new Thickness(0,0,8,0)};marker.SetResourceReference(Border.BackgroundProperty,"Peach");header.Children.Add(marker);var label=Theme.Text(title,12);label.FontWeight=FontWeights.Bold;header.Children.Add(label);children.Children.Add(header);var frame=new Border{Child=children,Padding=new Thickness(7),CornerRadius=new CornerRadius(9),BorderThickness=new Thickness(1),Margin=new Thickness(0,0,0,11)};frame.SetResourceReference(Border.BackgroundProperty,"Bg");frame.SetResourceReference(Border.BorderBrushProperty,"Line");System.Windows.Automation.AutomationProperties.SetName(frame,title+" navigation category");panel.Children.Add(frame);return children;}
  void AddNav(StackPanel panel,string name){var button=Theme.Button(name,()=>{if(name=="Profiles"){OpenProfiles();return;}if(name=="Preferences"){OpenPreferences();return;}Navigate(name);});button.Style=(Style)Application.Current.FindResource("NavigationButton");button.HorizontalContentAlignment=HorizontalAlignment.Left;button.Margin=new Thickness(0,2,0,2);button.Padding=new Thickness(14,10,8,10);System.Windows.Automation.AutomationProperties.SetName(button,name);navigation[name]=button;panel.Children.Add(button);}
  void UpdateNavigation(){foreach(var item in navigation){bool selected=item.Key==view;item.Value.Tag=selected?"selected":"";item.Value.SetResourceReference(Control.BackgroundProperty,selected?"Selection":"Bg");item.Value.SetResourceReference(Control.ForegroundProperty,selected?"Accent":"Ink");item.Value.FontWeight=selected?FontWeights.Bold:FontWeights.Normal;}}
  string PageNote(){switch(view){case "Home":return "Create a shortcut. Choose your input. Keep your flow.";case "All shortcuts":return "Search, edit and manage your assignments.";case "Keyboard shortcuts":return "Manage keyboard triggers, key combinations and keyboard-activated macros.";case "Mouse shortcuts":return "Assign buttons and wheel directions to your actions.";case "Touchpad gestures":return "Draw a shape to run an action. No activation key needed.";case "AI model":return "Your model, your choice. Connect once and reuse it.";case "Applications":return "Register an app, then give it a shortcut.";case "Conflicts":return "Review overlapping triggers and application priorities.";case "Appearance":return "Choose, design or import your own palette.";case "Settings":return "Appearance, playback speed and input behavior.";default:return "Manage your workspace.";}}
  UIElement ModelPanel(){var form=new StackPanel{MaxWidth=850,HorizontalAlignment=HorizontalAlignment.Left};form.Children.Add(Theme.Text("Choose the intelligence behind your prompts",23));form.Children.Add(Theme.Text("Bring a GGUF file or use a compatible API server. Makro+ does not bundle a language model.",14,"Muted"));var info=new StackPanel();info.Children.Add(Theme.Text(state.ModelOptions.Remote?"API SERVER":"LOCAL MODEL",11,"Muted"));info.Children.Add(Theme.Text(state.ModelOptions.Describe(state.ModelPath),21));info.Children.Add(Theme.Text(state.ModelOptions.Remote?"Prompts are sent to your configured server.":"Your chosen model runs on this computer. The first request loads it; later requests reuse the session.",13,"Muted"));var card=Theme.Card(info);card.Margin=new Thickness(0,20,0,16);form.Children.Add(card);var buttons=new WrapPanel();buttons.Children.Add(Theme.Button("Configure model",()=>{ConfigureModel();Render();},true));buttons.Children.Add(Theme.Button("Unload local model",()=>{LocalLlm.Shared.Stop();status.Text="Local model memory released.";}));form.Children.Add(buttons);form.Children.Add(Theme.Text("Local model folder: "+ModelFiles.DefaultDirectory,13,"Muted"));form.Children.Add(Theme.Text("Copy downloaded .gguf files into models next to MakroPlus.exe. Use Configure model → Open models folder. One file is detected automatically; select a file when there are several.",13,"Muted"));form.Children.Add(Theme.Text("Saved shortcuts run directly",20));form.Children.Add(Theme.Text("The model is used to create a plan. Pressing a saved shortcut executes that plan immediately, without another model request.",14,"Muted"));form.Children.Add(Theme.Button("Create a prompt shortcut",()=>OpenPrompt()));foreach(var text in form.Children)if(text is TextBlock)((TextBlock)text).Margin=new Thickness(0,12,0,6);form.Children.Add(status);return new ScrollViewer{Content=form,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};}
  void ConfigureModel(){var dialog=new ModelSettingsWindow(state.ModelOptions,state.ModelPath){Owner=this};if(dialog.ShowDialog()!=true)return;var old=state.ModelOptions;string oldPath=state.ModelPath;state.ModelOptions=dialog.Result;state.ModelPath=dialog.ModelPath;if(!Save()){state.ModelOptions=old;state.ModelPath=oldPath;}else LocalLlm.Shared.Stop();}
 }
 public static class InputSections {
  public static bool Keyboard(Binding binding,SystemShortcut external){if(binding!=null)return binding.Gesture==null&&binding.Key>0&&!InputKeys.IsPointer(binding.Key);if(external==null)return false;if(external.Key>0)return !InputKeys.IsPointer(external.Key);if(string.IsNullOrWhiteSpace(external.KeyText))return false;TriggerSpec trigger;return !TriggerSpec.TryParse(external.KeyText,out trigger)||!InputKeys.IsPointer(trigger.Key);}
 }
}
